DO $import$
DECLARE
  v_chunk jsonb := $batch161_01$[{"id":"document-title","kind":"title","text":"Постановление Министерства экономики Республики Беларусь от 30 сентября 2011 г. №161 «Об установлении нормативных сроков службы основных средств и признании утратившими силу некоторых постановлений Министерства экономики Республики Беларусь»","level":1},{"id":"document-date-number","kind":"paragraph","text":"30 сентября 2011 г. № 161","level":2},{"id":"appendix-normative-lives","kind":"section","text":"Нормативные сроки службы основных средств","level":1},{"id":"row-2","kind":"section","label":"1","text":"1 — ЗДАНИЯ","level":1},{"id":"row-3","kind":"chapter","label":"100","text":"100 — Здания производственные и непроизводственные","level":2},{"id":"code-10000","kind":"paragraph","label":"10000","text":"10000 — Здания высотные (более 25 этажей), особо капитальные, каркасно-монолитные, повышенной прочности, фундамент – монолитная плита на свайном основании, стены – алюминиевые панели с повышенной антикоррозионной защитой, перекрытия – железобетон, с облицовкой стилобата естественным камнем\nНормативный срок службы: 125 лет.","level":3},{"id":"code-10001","kind":"paragraph","label":"10001","text":"10001 — Здания многоэтажные (более 2 этажей); здания одноэтажные с железобетонными и металлическими каркасами, со стенами из каменных материалов, крупных блоков и панелей, с железобетонными, металлическими и другими долговечными перекрытиями и покрытиями с повышенной антикоррозионной защитой, с площадью пола более 5000 кв. м, приплотинные и подземные здания гидро-, гидроаккумулирующих электростанций\nНормативный срок службы: 100 лет.","level":3},{"id":"code-10002","kind":"paragraph","label":"10002","text":"10002 — Здания двухэтажные всех назначений и видов, кроме зданий деревянных; здания одноэтажные с железобетонными и металлическими каркасами, со стенами из каменных материалов, крупных блоков и панелей, с железобетонными, металлическими и другими долговечными перекрытиями и покрытиями, с площадью пола до 5000 кв. м\nНормативный срок службы: 75 лет.","level":3},{"id":"code-10003","kind":"paragraph","label":"10003","text":"10003 — Здания многоэтажные типа этажерок специального технологического назначения (корпуса обогатительных фабрик, дробильных, размольных, химических цехов и других аналогичных производств); бомбоубежища; здания одноэтажные бескаркасные со стенами из каменных материалов, крупных блоков и панелей, с железобетонными, кирпичными и деревянными колоннами и столбами, с железобетонными, металлическими и другими перекрытиями и покрытиями, здания деревянные с облицовкой\nНормативный срок службы: 50 лет.","level":3},{"id":"code-10004","kind":"paragraph","label":"10004","text":"10004 — Здания одноэтажные бескаркасные со стенами облегченной каменной кладки, с железобетонными, кирпичными и деревянными колоннами и столбами; здания деревянные с брусчатыми или бревенчатыми рублеными стенами независимо от этажности; стационарные общественные туалеты, сборно-щитовые здания с облицовкой\nНормативный срок службы: 40 лет.","level":3},{"id":"code-10005","kind":"paragraph","label":"10005","text":"10005 — Здания деревянные, каркасные и щитовые, контейнерные, деревометаллические, каркасно-обшивные и панельные независимо от этажности; склады арочного типа\nНормативный срок службы: 20 лет.","level":3},{"id":"row-10","kind":"paragraph","text":"Здания мобильные (в том числе здания сборно-разборные и передвижные)","level":3},{"id":"code-10007","kind":"paragraph","label":"10007","text":"10007 — Здания каркасно-панельные и панельные, щитовые и прочие облегченные здания\nНормативный срок службы: 10 лет.","level":3},{"id":"code-10008","kind":"paragraph","label":"10008","text":"10008 — Здания каркасно-панельные и панельные с металлическим и деревянным каркасом, с ограждающими конструкциями из железобетонных и асбошиферных панелей; каркасно-панельные и панельные с металлическим и деревянным каркасом, с ограждающими конструкциями из металлического листа, навесы со стенами, склады арочного типа, металлические; здания испытательных станций\nНормативный срок службы: 20 лет.","level":3},{"id":"row-13","kind":"paragraph","text":"Здания мобильные:","level":3},{"id":"code-10009","kind":"paragraph","label":"10009","text":"10009 — цельнометаллические\nНормативный срок службы: 10 лет.","level":3},{"id":"code-10010","kind":"paragraph","label":"10010","text":"10010 — деревометаллические\nНормативный срок службы: 8 лет.","level":3},{"id":"code-10011","kind":"paragraph","label":"10011","text":"10011 — Палатки-магазины, павильоны, кафе, закусочные, столовые из металлоконструкций, стеклопластика, прессованных плит и деревянные\nНормативный срок службы: 15 лет.\nПримечание: сноска 1.","level":3},{"id":"code-10012","kind":"paragraph","label":"10012","text":"10012 — Киоски и ларьки из металлоконструкций, стеклопластика, прессованных плит и деревянные\nНормативный срок службы: 9 лет.\nПримечание: сноска 2.","level":3},{"id":"row-18","kind":"paragraph","text":"Здания прочие","level":3},{"id":"code-10015","kind":"paragraph","label":"10015","text":"10015 — Хранилища для зерна, фруктов, овощей и картофеля с каменными стенами из штучных камней и блоков, колонны железобетонные, кирпичные и деревянные, покрытия железобетонные или асбестоцементные листы по деревянной обрешетке, кровля рулонная\nНормативный срок службы: 28 лет.","level":3},{"id":"code-10016","kind":"paragraph","label":"10016","text":"10016 — Здания с железобетонными и металлическими каркасами, со стенами из трехслойных металлических панелей с утеплением из минераловатных плит (сэндвич-панелей), с железобетонными, металлическими и другими долговечными перекрытиями\nНормативный срок службы: 50 лет.","level":3},{"id":"row-21","kind":"chapter","label":"101","text":"101 — Здания жилые","level":2},{"id":"code-10100","kind":"paragraph","label":"10100","text":"10100 — Здания каменные, особо капитальные, стены кирпичные, в том числе с железобетонным или металлическим каркасом, перекрытия железобетонные, бетонные или деревянные; с крупноблочными стенами, перекрытия железобетонные\nНормативный срок службы: 125 лет.","level":3},{"id":"code-10102","kind":"paragraph","label":"10102","text":"10102 — Здания со стенами облегченной кладки из кирпича, монолитного шлакобетона\nНормативный срок службы: 100 лет.","level":3},{"id":"code-10103","kind":"paragraph","label":"10103","text":"10103 — Здания со стенами смешанными, деревянными рублеными или брусчатыми, сборно-щитовыми, облицованными кирпичом\nНормативный срок службы: 50 лет.","level":3},{"id":"code-10104","kind":"paragraph","label":"10104","text":"10104 — Здания сборно-щитовые, каркасно-засыпные\nНормативный срок службы: 30 лет.","level":3},{"id":"code-10105","kind":"paragraph","label":"10105","text":"10105 — Здания с крупнопанельными стенами, перекрытия железобетонные\nНормативный срок службы: 80 лет.","level":3},{"id":"row-27","kind":"section","label":"2","text":"2 — СООРУЖЕНИЯ","level":1},{"id":"row-28","kind":"chapter","label":"200","text":"200 — Скважины нефтяные и газовые","level":2},{"id":"code-20000","kind":"paragraph","label":"20000","text":"20000 — Скважины нефтяные, нагнетательные и контрольные\nНормативный срок службы: 14 лет.","level":3},{"id":"code-20001","kind":"paragraph","label":"20001","text":"20001 — Скважины газовые и газоконденсатные; трубопроводы обвязочные и шлейфы скважин\nНормативный срок службы: 12 лет.","level":3},{"id":"code-20002","kind":"paragraph","label":"20002","text":"20002 — Скважины подземных хранилищ газа, в том числе разведочные\nНормативный срок службы: 50 лет.","level":3},{"id":"row-32","kind":"paragraph","text":"Сооружения магистрального трубопроводного транспорта","level":3},{"id":"code-20010","kind":"paragraph","label":"20010","text":"20010 — Газопроводы, нефтепроводы и нефтепродуктопроводы магистральные, трубопроводы транспортные с компенсаторами линейными, воздуховодами, затворами, отводами, тройниками, люками-лазами, люками ревизионными; камеры пропуска, пуска и приема очистных и диагностических устройств, фильтры-грязеуловители, водогрязесборники; газопроводы технологические и отводы; станции газораспределительные, газоизмерительные\nНормативный срок службы: 33 лет.","level":3},{"id":"code-20011","kind":"paragraph","label":"20011","text":"20011 — Сосуды и аппараты емкостные для компримированного природного газа; установки для производства компримированного природного газа в блочном комплектном исполнении\nНормативный срок службы: 20 лет.","level":3},{"id":"code-20012","kind":"paragraph","label":"20012","text":"20012 — Подземные хранилища нефти и газа в отложениях калийной соли; буферный газ подземных хранилищ газа\nНормативный срок службы: 50 лет.","level":3},{"id":"code-20013","kind":"paragraph","label":"20013","text":"20013 — Сооружения электрохимической защиты от коррозии\nНормативный срок службы: 15 лет.","level":3},{"id":"code-20014","kind":"paragraph","label":"20014","text":"20014 — Обустройство устья скважин\nНормативный срок службы: 10 лет.\nПримечание: сноска 94.","level":3},{"id":"row-38","kind":"chapter","label":"201","text":"201 — Сооружения гидротехнические\nПримечание: сноска 3.","level":2},{"id":"code-20100","kind":"paragraph","label":"20100","text":"20100 — Сеть осушительная при разработке торфа и сооружения на ней\nНормативный срок службы: 7 лет.","level":3},{"id":"code-20101","kind":"paragraph","label":"20101","text":"20101 — Плотины бетонные, железобетонные, каменные; тоннели; тонкостенные водосливы и водоприемники, отстойники, лотки и водопроводящие сооружения, рыбопропускные и рыбозащитные сооружения; напорные трубопроводы и уравнительные резервуары; деривационные каналы, напорные бассейны гидро-, гидроаккумулирующих электростанций; шлюзы судоходные и судоподъемники; дамбы ограждающие земляные\nНормативный срок службы: 100 лет.","level":3},{"id":"code-20102","kind":"paragraph","label":"20102","text":"20102 — Сооружения берегоукрепительные и берегозащитные железобетонные, бетонные, каменные; сооружения гидротехнические деревянные (включая здания)\nНормативный срок службы: 29 лет.","level":3},{"id":"code-20103","kind":"paragraph","label":"20103","text":"20103 — Гидрометрические водоемные станции на реках\nНормативный срок службы: 20 лет.","level":3},{"id":"code-20104","kind":"paragraph","label":"20104","text":"20104 — Каналы судоходные\nНормативный срок службы: 125 лет.","level":3},{"id":"code-20105","kind":"paragraph","label":"20105","text":"20105 — Сооружения регулированные (выпрямительные) всех видов, водомерные посты на каналах, водомерные створы\nНормативный срок службы: 8 лет.","level":3},{"id":"code-20106","kind":"paragraph","label":"20106","text":"20106 — Водохранилища при земляных плотинах, при гидроэлектростанциях\nНормативный срок службы: 74 лет.","level":3},{"id":"row-46","kind":"paragraph","text":"Водосбросы и водовыпуски при прудах:","level":3},{"id":"code-20107","kind":"paragraph","label":"20107","text":"20107 — бетонные и железобетонные\nНормативный срок службы: 50 лет.","level":3},{"id":"code-20108","kind":"paragraph","label":"20108","text":"20108 — деревянные\nНормативный срок службы: 12 лет.","level":3},{"id":"code-20109","kind":"paragraph","label":"20109","text":"20109 — Сооружения выпрямительные фашинные и каменные\nНормативный срок службы: 20 лет.","level":3},{"id":"code-20110","kind":"paragraph","label":"20110","text":"20110 — Сооружения гидротехнические на каналах (шлюзы-регуляторы, трубы-регуляторы, мосты, трубы-переезды, перепады, быстротоки, консольные перепады, дюкеры, в том числе стальные, акведуки, водосливы бетонные и железобетонные)\nНормативный срок службы: 40 лет.","level":3},{"id":"code-20111","kind":"paragraph","label":"20111","text":"20111 — Водопровод с поилками\nНормативный срок службы: 5 лет.","level":3},{"id":"code-20112","kind":"paragraph","label":"20112","text":"20112 — Реки-водоприемники отрегулированные, межхозяйственные, осушительные, магистральные и другие проводящие каналы, внутрихозяйственные осушительные каналы земляные без крепления и с креплением плетнем, фашинами, досками и засевом трав в торфяных грунтах; в земляном русле без облицовки; каналы из железобетонных лотков, водосборно-сборная сеть в земляном русле, коллекторно-дренажные каналы в земляном русле, бассейны испарительные для соли\nНормативный срок службы: 30 лет.","level":3},{"id":"row-53","kind":"paragraph","text":"Дренаж (горизонтальный) для осушения сельскохозяйственных земель:","level":3},{"id":"code-20113","kind":"paragraph","label":"20113","text":"20113 — гончарный в минеральных грунтах\nНормативный срок службы: 50 лет.","level":3},{"id":"code-20114","kind":"paragraph","label":"20114","text":"20114 — гончарный в торфяных грунтах; пластмассовый\nНормативный срок службы: 40 лет.","level":3},{"id":"code-20115","kind":"paragraph","label":"20115","text":"20115 — дощатый, хворостяной\nНормативный срок службы: 14 лет.","level":3},{"id":"code-20116","kind":"paragraph","label":"20116","text":"20116 — щелевой, кротовый\nНормативный срок службы: 4 лет.","level":3},{"id":"row-58","kind":"paragraph","text":"Скважины вертикального дренажа:","level":3},{"id":"code-20117","kind":"paragraph","label":"20117","text":"20117 — скважины в агрессивной среде\nНормативный срок службы: 10 лет.","level":3},{"id":"code-20118","kind":"paragraph","label":"20118","text":"20118 — скважины в нормальных условиях\nНормативный срок службы: 15 лет.","level":3},{"id":"code-20119","kind":"paragraph","label":"20119","text":"20119 — водовыпуски и сбросные сооружения\nНормативный срок службы: 25 лет.","level":3},{"id":"code-20120","kind":"paragraph","label":"20120","text":"20120 — Сооружения морские и речные причальные гравитационные из бетонных массивов\nНормативный срок службы: 58 лет.","level":3},{"id":"code-20121","kind":"paragraph","label":"20121","text":"20121 — Каналы открытые регулирующие, оградительные, нагорноловочные в минеральных и торфяных грунтах без крепления для осушения сельскохозяйственных земель\nНормативный срок службы: 20 лет.","level":3},{"id":"row-64","kind":"paragraph","text":"Сооружения оградительные:","level":3},{"id":"code-20122","kind":"paragraph","label":"20122","text":"20122 — земляные, бетонные и железобетонные\nНормативный срок службы: 90 лет.\nПримечание: сноска 95.","level":3},{"id":"code-20123","kind":"paragraph","label":"20123","text":"20123 — металлические и деревянные\nНормативный срок службы: 50 лет.","level":3},{"id":"code-20124","kind":"paragraph","label":"20124","text":"20124 — Плотины и дамбы земляные без облицовки, кроме плотин и дамб при крупных гидростанциях и прудах, и речные оградительные сооружения\nНормативный срок службы: 76 лет.","level":3},{"id":"code-20125","kind":"paragraph","label":"20125","text":"20125 — Шлюзы судоходные деревянные и смешанной конструкции, плотины деревянные\nНормативный срок службы: 50 лет.","level":3},{"id":"code-20126","kind":"paragraph","label":"20126","text":"20126 — Сооружения выправительные из грунта с гравийным, щебеночным или тюфячным покрытием и фашинно-кольевые\nНормативный срок службы: 5 лет.","level":3},{"id":"row-70","kind":"paragraph","text":"Сооружения речные причальные:","level":3},{"id":"code-20127","kind":"paragraph","label":"20127","text":"20127 — железобетонные, бетонные и каменные\nНормативный срок службы: 62 лет.","level":3},{"id":"code-20128","kind":"paragraph","label":"20128","text":"20128 — металлические\nНормативный срок службы: 40 лет.","level":3},{"id":"code-20129","kind":"paragraph","label":"20129","text":"20129 — деревянные эстакады, ряжевые набережные, больверки, пристани\nНормативный срок службы: 25 лет.","level":3},{"id":"code-20130","kind":"paragraph","label":"20130","text":"20130 — Сооружения водоприемные для открытых источников, включая крепление береговой полосы (для водоснабжения)\nНормативный срок службы: 50 лет.","level":3},{"id":"row-75","kind":"paragraph","text":"Сооружения наплавные лесозадерживающие, лесонаправляющие, оградительные и причальные:","level":3},{"id":"code-20131","kind":"paragraph","label":"20131","text":"20131 — деревянные\nНормативный срок службы: 4 лет.","level":3},{"id":"code-20132","kind":"paragraph","label":"20132","text":"20132 — металлические\nНормативный срок службы: 10 лет.","level":3},{"id":"row-78","kind":"paragraph","text":"Опоры наплавных сооружений:","level":3},{"id":"code-20133","kind":"paragraph","label":"20133","text":"20133 — деревянные\nНормативный срок службы: 5 лет.","level":3},{"id":"code-20134","kind":"paragraph","label":"20134","text":"20134 — железобетонные\nНормативный срок службы: 20 лет.","level":3},{"id":"code-20135","kind":"paragraph","label":"20135","text":"20135 — Плотины лесосплавные и мелиоративные; водозаборные, водосбросные сооружения деревянные\nНормативный срок службы: 12 лет.","level":3},{"id":"code-20136","kind":"paragraph","label":"20136","text":"20136 — Лотки лесосплавные железобетонные\nНормативный срок службы: 20 лет.","level":3},{"id":"row-83","kind":"paragraph","text":"Сооружения прудовые рыбоводные","level":3},{"id":"code-20145","kind":"paragraph","label":"20145","text":"20145 — Плотины земляные при прудах, дамбы нагульных прудов без креплений\nНормативный срок службы: 30 лет.","level":3},{"id":"code-20146","kind":"paragraph","label":"20146","text":"20146 — Водосбросы, водовыпуски и водоспуски при прудах, садки для хранения рыбы и рыбоуловители, бетонные и железобетонные\nНормативный срок службы: 28 лет.","level":3},{"id":"code-20148","kind":"paragraph","label":"20148","text":"20148 — Каналы при прудах рыбосборные\nНормативный срок службы: 3 лет.","level":3},{"id":"code-20149","kind":"paragraph","label":"20149","text":"20149 — Бассейны железобетонные для содержания и выращивания рыбы\nНормативный срок службы: 25 лет.","level":3},{"id":"row-88","kind":"paragraph","text":"Линии из стеклопластиковых лотков или бассейнов для содержания и выращивания рыбы:","level":3},{"id":"code-20150","kind":"paragraph","label":"20150","text":"20150 — железобетонные основания\nНормативный срок службы: 25 лет.","level":3},{"id":"cod